#!/usr/bin/env python3
"""F1 Rubric + model answers (Phase 9, Builder A) — injektor reveal-after-write.

Menambahkan panel <details class="reveal-panel"> "Tulis dulu, lalu bandingkan"
di setiap modul yang punya jurnal 3-lensa (modul-1..modul-35) + halaman
analisis-mingguan. Statis: tanpa grading otomatis, tanpa backend.
Idempotent: modul yang sudah punya panel dilewati.

Isi panel: rubrik self-check (4 checklist, teks sama semua modul) + 1 exemplar
jawaban model per modul (150-250 kata, Bahasa Indonesia, istilah English,
angka dari CANONICAL-DATA.md; angka ilustratif di luar kanonis dilabel).
"""
import os, re, sys

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

RUBRIC_ITEMS = [
    "Ada <strong>vonis eksplisit</strong> — BELI / TAHAN / JUAL, APPROVE / CONDITIONAL / DECLINE, atau setara. Bukan sekadar ringkasan angka.",
    "Mengutip <strong>&ge;3 angka dari laporan</strong> — dengan satuan dan tahunnya. Bukan &ldquo;bagus&rdquo; atau &ldquo;naik&rdquo;.",
    "Menyebut <strong>1 hal yang bisa membunuh tesis ini</strong> — risiko yang kamu akui sendiri, bukan risiko versi orang lain.",
    "<strong>Tiap lensa terwakili</strong> — investasi (return vs risiko), kredit (kemampuan bayar), forensik (apa yang perlu diverifikasi).",
]

def panel_html(exemplar, note=False):
    items = "".join(
        '<label class="rubric-item"><input type="checkbox"> <span>%s</span></label>' % it
        for it in RUBRIC_ITEMS
    )
    head = "Contoh note model (kedua)" if note else "Contoh jawaban model"
    tail = ("Contoh di atas bukan kunci jawaban &mdash; ia menunjukkan <em>bentuk</em> note "
            "yang lolos rubrik: vonis + angka + risiko + lima blok. Nilai sendiri: berapa dari "
            "4 checklist yang tercentang di notemu?") if note else \
           ("Contoh di atas bukan kunci jawaban &mdash; ia menunjukkan <em>bentuk</em> jawaban "
            "yang lolos rubrik: vonis + angka + risiko + tiga lensa. Nilai sendiri: berapa dari "
            "4 checklist yang tercentang di jurnalmu?")
    return (
        '<details class="reveal-panel">\n'
        '  <summary>Tulis dulu, lalu bandingkan</summary>\n'
        '  <div class="reveal-body">\n'
        '    <h3>Rubrik self-check</h3>\n'
        '    <p class="sub">Tulis dulu jawabanmu di atas &mdash; baru buka panel ini. Centang yang sudah kamu penuhi:</p>\n'
        + items + '\n'
        '    <h3>%s</h3>\n'
        '    <div class="exemplar">\n%s\n    </div>\n'
        '    <p class="sub">%s</p>\n'
        '  </div>\n'
        '</details>'
    ) % (head, exemplar, tail)

