# ------------------------------------------------------------------ injeksi
def find_journal_close(src):
    """Kembalikan index tepat setelah </div> penutup <div class="journal">."""
    start = src.find('<div class="journal">')
    if start < 0:
        return -1
    depth = 0
    i = start
    n = len(src)
    while i < n:
        if src.startswith('<div', i):
            depth += 1
            i += 4
        elif src.startswith('</div>', i):
            depth -= 1
            i += 6
            if depth == 0:
                return i
        else:
            i += 1
    return -1

def inject_module(path, num):
    with open(path, encoding='utf-8') as f:
        src = f.read()
    if 'reveal-panel' in src:
        return 'skip'
    pos = find_journal_close(src)
    if pos < 0:
        return 'NO-JOURNAL'
    panel = panel_html(EX[num])
    src = src[:pos] + "\n" + panel + src[pos:]
    with open(path, 'w', encoding='utf-8') as f:
        f.write(src)
    return 'ok'

def inject_weekly(path):
    with open(path, encoding='utf-8') as f:
        src = f.read()
    if 'reveal-panel' in src:
        return 'skip'
    anchor = '<button class="btn btn-primary" id="note-save">Simpan note hari ini</button></p>'
    if anchor not in src:
        return 'NO-ANCHOR'
    panel = panel_html(WEEKLY, note=True)
    src = src.replace(anchor, anchor + "\n" + panel, 1)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(src)
    return 'ok'

def main():
    results = {}
    for num in range(1, 38):
        p = os.path.join(BASE, 'modul-%d' % num, 'index.html')
        if num not in EX:
            results[num] = 'NO-EXEMPLAR'
            continue
        results[num] = inject_module(p, num) if os.path.exists(p) else 'MISSING-FILE'
    results['weekly'] = inject_weekly(os.path.join(BASE, 'analisis-mingguan', 'index.html'))
    ok = sum(1 for v in results.values() if v == 'ok')
    print("injected:", ok)
    for k, v in sorted(results.items(), key=lambda x: str(x[0])):
        if v != 'ok':
            print(" ", k, v)
    return 0 if all(v in ('ok', 'skip') for v in results.values()) else 1

if __name__ == '__main__':
    sys.exit(main())
